import { createNode, autoLayout } from '../packages/graph/src/index.js';
function project(name, description, domain = { min: [-36, -31, -34], max: [36, 31, 34] }) { return { format: 'implicitforge', version: 1, name, description, units: 'mm', nodes: [], root: null, assets: {}, domain, material: { name: 'Aluminium 6061', density: 2.7, E: 69000, nu: .33, conductivity: 167 }, view: { color: [.88, .38, .17], roughness: .32 } }; }
function add(d, type, name, params = {}, inputs = {}) { const n = createNode(type, { name, inputs }); Object.assign(n.params, params); d.nodes.push(n); d.root = n.id; return n.id; }
function finish(d, root) { d.root = root; autoLayout(d); return d; }
function exchanger() {
    const d = project('Aero / graded heat exchanger', 'A field-graded gyroid core with machined manifolds and a central flow passage.');
    const envelope = add(d, 'box', 'Core envelope', { size: [46, 36, 42], radius: 3 });
    const ramp = add(d, 'ramp', 'Axial wall gradient', { start: -21, end: 21, low: .36, high: .72 });
    const core = add(d, 'gyroid', 'Graded gyroid core', { cell: 10.5, thickness: .55 }, { domain: envelope, thickness: ramp });
    const plate = add(d, 'box', 'Manifold blank', { size: [56, 46, 4], radius: 1.6 });
    const base = add(d, 'translate', 'Lower manifold', { offset: [0, 0, -22.5] }, { body: plate });
    const top = add(d, 'translate', 'Upper manifold', { offset: [0, 0, 22.5] }, { body: plate });
    const plates = add(d, 'union', 'Manifold pair', {}, { a: base, b: top });
    const joined = add(d, 'union', 'Core + manifolds', {}, { a: core, b: plates });
    const bore = add(d, 'cylinder', 'Flow passage', { radius: 6, height: 64 });
    const open = add(d, 'subtract', 'Open flow passage', {}, { a: joined, b: bore });
    const hole = add(d, 'cylinder', 'Fastener tool', { radius: 2.15, height: 64 });
    const array = add(d, 'repeat', 'Mounting pattern', { spacing: [23, 18, 70], count: [3, 3, 1] }, { body: hole });
    const root = add(d, 'subtract', 'Heat exchanger', {}, { a: open, b: array });
    d.view.color = [.91, .40, .20];
    return finish(d, root);
}
function gyroidCube() { const d = project('Gyroid / material study', 'A clean field-driven lattice coupon for comparing cell families.', { min: [-28, -28, -28], max: [28, 28, 28] }); const body = add(d, 'box', 'Rounded design domain', { size: [42, 42, 42], radius: 3 }); const field = add(d, 'radial', 'Radial density gradient', { radius: 32, inner: .8, outer: .32 }); const root = add(d, 'gyroid', 'Gyroid coupon', { cell: 13 }, { domain: body, thickness: field }); d.view.color = [.25, .68, .68]; return finish(d, root); }
function bracket() { const d = project('Bracket / lightweight mount', 'A connected mount with an implicit fillet and two mounting holes.', { min: [-37, -26, -12], max: [37, 26, 55] }); const a = add(d, 'box', 'Horizontal leg', { size: [58, 34, 7], radius: 2 }); const b = add(d, 'box', 'Vertical leg', { size: [7, 34, 50], radius: 2 }); const bb = add(d, 'translate', 'Locate upright', { offset: [-25, 0, 21.5] }, { body: b }); const base = add(d, 'smoothUnion', 'Filleted bracket', { radius: 7 }, { a, b: bb }); const drill = add(d, 'cylinder', 'Mount hole tool', { radius: 3.8, height: 100 }); const h1 = add(d, 'translate', 'Mount hole A', { offset: [15, 9, 0] }, { body: drill }); const h2 = add(d, 'translate', 'Mount hole B', { offset: [15, -9, 0] }, { body: drill }); const holes = add(d, 'union', 'Mount holes', {}, { a: h1, b: h2 }); const root = add(d, 'subtract', 'Bracket', {}, { a: base, b: holes }); d.view.color = [.32, .58, .79]; return finish(d, root); }
function toroid() { const d = project('Toroid / Schwarz lattice', 'Triply periodic shelling in a toroidal design space.', { min: [-36, -36, -20], max: [36, 36, 20] }); const body = add(d, 'torus', 'Toroidal envelope', { major: 22, minor: 9 }); const f = add(d, 'sine', 'Circumferential grading', { direction: [1, 1, 0], period: 46, base: .48, amplitude: .15 }); const root = add(d, 'schwarz', 'Schwarz P toroid', { cell: 10 }, { domain: body, thickness: f }); d.view.color = [.75, .64, .33]; return finish(d, root); }
function octet() { const d = project('Octet / structural coupon', 'Periodic face-diagonal beams with a field-varying strut radius.', { min: [-30, -30, -34], max: [30, 30, 34] }); const body = add(d, 'cylinder', 'Cylindrical domain', { radius: 22, height: 50 }); const f = add(d, 'ramp', 'Strut radius ramp', { start: -25, end: 25, low: .6, high: 1.1 }); const root = add(d, 'octet', 'Octet beam coupon', { cell: 10, radius: .7 }, { domain: body, radius: f }); d.view.color = [.60, .63, .74]; return finish(d, root); }
function cantilever() { const d = project('Cantilever / analysis benchmark', 'A solid cantilever for finite-element and topology-optimization experiments.', { min: [-30, -12, -12], max: [30, 12, 12] }); const root = add(d, 'box', 'Cantilever design space', { size: [58, 20, 20], radius: .5 }); d.view.color = [.49, .62, .82]; return finish(d, root); }
function diamond() { const d = project('Diamond / twisted column', 'Diamond nodal sheet warped by a coordinate-space twist.', { min: [-28, -28, -38], max: [28, 28, 38] }); const body = add(d, 'box', 'Column envelope', { size: [32, 32, 56], radius: 4 }); const lat = add(d, 'diamond', 'Diamond sheet', { cell: 15, thickness: .43 }, { domain: body }); const root = add(d, 'twist', 'Twisted diamond', { rate: 1.6 }, { body: lat }); d.view.color = [.53, .65, .36]; return finish(d, root); }
function blank() { return project('Untitled / implicit design', 'Start with a primitive, then connect fields and operations.'); }
export const EXAMPLES = [{ id: 'exchanger', name: 'Graded heat exchanger', category: 'FIELD-DRIVEN DESIGN', description: 'Gyroid core · machined manifolds', make: exchanger }, { id: 'gyroid', name: 'Gyroid material study', category: 'LATTICE DESIGN', description: 'Radial grading · TPMS sheet', make: gyroidCube }, { id: 'bracket', name: 'Lightweight mounting bracket', category: 'IMPLICIT MODELING', description: 'Smooth booleans · subtractive tools', make: bracket }, { id: 'toroid', name: 'Schwarz P toroid', category: 'LATTICE DESIGN', description: 'Toroidal domain · wave field', make: toroid }, { id: 'octet', name: 'Octet structural coupon', category: 'BEAM LATTICES', description: 'Periodic struts · axial grading', make: octet }, { id: 'cantilever', name: 'Cantilever benchmark', category: 'SIMULATION & OPTIMIZATION', description: 'Hex8 FEM · SIMP topology', make: cantilever }, { id: 'diamond', name: 'Twisted diamond column', category: 'COORDINATE TRANSFORMS', description: 'Diamond sheet · implicit warp', make: diamond }, { id: 'blank', name: 'Empty notebook', category: 'NEW PROJECT', description: 'Build a graph from first principles', make: blank }];
